'use client'
import { useEffect, useState } from 'react'
import dynamic from 'next/dynamic'
import { motion, AnimatePresence } from 'framer-motion'
import CountryPanel from '@/components/atlas/CountryPanel'
import { supabase } from '@/lib/supabase'
import { severityColor } from '@/lib/design-tokens'
import { MOCK_COUNTRIES } from '@/lib/mock-data'

const USE_MOCK = true // set false to fetch from Supabase

const LeafletMap = dynamic(() => import('@/components/atlas/LeafletMap'), {
  ssr: false,
  loading: () => (
    <div style={{ width: '100%', height: '100%', background: 'var(--bg)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: 12 }}>
      <div style={{ width: 20, height: 20, border: '2px solid var(--line-2)', borderTopColor: 'var(--accent)', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      <span style={{ fontFamily: 'var(--mono)', fontSize: 9, color: 'var(--text-3)', letterSpacing: '0.14em', textTransform: 'uppercase' }}>Cargando mapa…</span>
    </div>
  ),
})

type Country = { iso3: string; name: string; flag: string; lat: number; lng: number; iea: number | null }

function dotColor(iea: number | null): { color: string; pulse: boolean } {
  if (iea === null) return { color: 'var(--line-2)', pulse: false }
  if (iea < 30)    return { color: '#22d3a0', pulse: false }
  if (iea < 50)    return { color: '#facc15', pulse: false }
  if (iea < 70)    return { color: '#fb923c', pulse: false }
  return                   { color: '#f43f5e', pulse: true  }
}

const ROW_VARIANTS = {
  hidden: { opacity: 0, x: -8 },
  show:   (i: number) => ({ opacity: 1, x: 0, transition: { duration: 0.3, delay: i * 0.03, ease: 'easeOut' as const } }),
}

export default function AtlasPage() {
  const [countries, setCountries] = useState<Country[]>([])
  const [selected,  setSelected]  = useState<string | null>(null)
  const [loading,   setLoading]   = useState(true)
  const [search,    setSearch]    = useState('')

  useEffect(() => {
    if (USE_MOCK) { setCountries(MOCK_COUNTRIES); setLoading(false); return }
    ;(async () => {
      const { data: c } = await supabase
        .from('countries').select('id,iso_alpha3,name_es,latitude,longitude,flag_emoji').eq('active', true)
      if (!c?.length) { setLoading(false); return }

      const { data: iea } = await supabase
        .from('iea_scores').select('country_id,iea_score').in('country_id', c.map(x => x.id)).order('period', { ascending: false })

      const latest: Record<string, number> = {}
      iea?.forEach(r => { if (!(r.country_id in latest)) latest[r.country_id] = r.iea_score })

      setCountries(
        c.map(x => ({
          iso3: x.iso_alpha3 as string,
          name: x.name_es   as string,
          flag: (x.flag_emoji as string) ?? '',
          lat:  (x.latitude  as number)  ?? 0,
          lng:  (x.longitude as number)  ?? 0,
          iea:  latest[x.id as string]   ?? null,
        })).sort((a, b) => (a.iea ?? 999) - (b.iea ?? 999))
      )
      setLoading(false)
    })()
  }, [])

  const filtered = countries.filter(c =>
    !search || c.name.toLowerCase().includes(search.toLowerCase()) || c.iso3.toLowerCase().includes(search.toLowerCase())
  )

  const panelOpen = !!selected

  return (
    <div style={{ display: 'grid', gridTemplateColumns: `264px 1fr${panelOpen ? ' 372px' : ''}`, height: '100%', transition: 'grid-template-columns .35s var(--ease)', overflow: 'hidden' }}>

      {/* ── Left: Rankings ──────────────────────────────────── */}
      <div style={{ background: 'var(--bg-2)', borderRight: '1px solid var(--line-2)', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>

        {/* Header */}
        <div style={{ padding: '14px 16px 10px', borderBottom: '1px solid var(--line)', flexShrink: 0 }}>
          {/* Section label with flanking lines */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
            <div style={{ flex: 1, height: 1, background: 'var(--accent)', opacity: 0.25 }} />
            <span style={{ fontFamily: 'var(--mono)', fontSize: 8, letterSpacing: '0.22em', textTransform: 'uppercase', color: 'var(--accent)' }}>
              Ranking IEA
            </span>
            <div style={{ flex: 1, height: 1, background: 'var(--accent)', opacity: 0.25 }} />
          </div>
          <div style={{ fontFamily: 'var(--mono)', fontSize: 8, color: 'var(--text-4)', textAlign: 'center', marginBottom: 10, letterSpacing: '0.07em' }}>
            {loading ? '…' : `${countries.length} países · 2023`}
          </div>
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Buscar país…"
            style={{
              width: '100%', background: 'rgba(56,189,248,.04)',
              border: '1px solid var(--line-2)',
              color: 'var(--text)', fontFamily: 'var(--mono)', fontSize: 12,
              padding: '7px 10px', outline: 'none',
              transition: 'border-color .18s, background .18s, box-shadow .18s',
            }}
            onFocus={e => { e.currentTarget.style.borderColor = 'var(--accent)'; e.currentTarget.style.background = 'rgba(56,189,248,.08)'; e.currentTarget.style.boxShadow = '0 0 0 3px rgba(56,189,248,.1)' }}
            onBlur={e  => { e.currentTarget.style.borderColor = 'var(--line-2)'; e.currentTarget.style.background = 'rgba(56,189,248,.04)'; e.currentTarget.style.boxShadow = 'none' }}
          />
        </div>

        {/* Rows */}
        <div style={{ flex: 1, overflowY: 'auto' }}>
          <style>{`::-webkit-scrollbar{width:2px}::-webkit-scrollbar-thumb{background:var(--line-2)}`}</style>
          {loading ? (
            <div style={{ padding: '12px 14px', display: 'flex', flexDirection: 'column', gap: 4 }}>
              {Array.from({ length: 12 }).map((_, i) => (
                <div key={i} style={{ height: 36, background: 'var(--bg-3)', backgroundImage: 'linear-gradient(90deg, transparent 25%, var(--bg-4) 50%, transparent 75%)', backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite' }} />
              ))}
            </div>
          ) : (
            <motion.div initial="hidden" animate="show">
              {filtered.map((c, i) => {
                const dot = dotColor(c.iea)
                const active = c.iso3 === selected
                return (
                  <motion.div
                    key={c.iso3}
                    custom={i}
                    variants={ROW_VARIANTS}
                    onClick={() => setSelected(active ? null : c.iso3)}
                    style={{
                      display: 'grid', gridTemplateColumns: '24px 22px 1fr 50px 10px',
                      gap: 6, alignItems: 'center',
                      padding: '8px 14px 8px 16px', cursor: 'pointer',
                      borderLeft: `2px solid ${active ? 'var(--accent)' : 'transparent'}`,
                      background: active ? 'var(--bg-4)' : 'transparent',
                      boxShadow: active ? 'inset 0 0 20px rgba(56,189,248,.04)' : 'none',
                      borderBottom: '1px solid var(--line)',
                      transition: 'background .12s, border-left-color .12s',
                    }}
                    onHoverStart={() => {}}
                    whileHover={active ? {} : { backgroundColor: 'rgba(16,30,52,1)' }}
                  >
                    <span style={{ fontFamily: 'var(--mono)', fontSize: 8.5, color: 'var(--text-4)', textAlign: 'right' }}>
                      {String(i + 1).padStart(2, '0')}
                    </span>
                    <span style={{ fontSize: 12, textAlign: 'center' }}>{c.flag}</span>
                    <span style={{ fontSize: 12.5, color: active ? 'var(--text)' : 'var(--text-2)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', transition: 'color .12s' }}>
                      {c.name}
                    </span>
                    <span style={{ fontFamily: 'var(--mono)', fontSize: 11, fontWeight: 500, textAlign: 'right', color: active ? 'var(--accent)' : 'var(--text-2)', transition: 'color .12s' }}>
                      {c.iea !== null ? c.iea.toFixed(1) : '—'}
                    </span>
                    <div style={{
                      width: 7, height: 7, borderRadius: '50%',
                      background: dot.color,
                      animation: dot.pulse ? 'pulse 1.8s ease-in-out infinite' : 'none',
                    }} />
                  </motion.div>
                )
              })}
            </motion.div>
          )}
        </div>
      </div>

      {/* ── Center: Map ─────────────────────────────────────── */}
      <div style={{ position: 'relative', overflow: 'hidden', background: 'var(--bg)' }}>
        <LeafletMap
          scores={countries}
          selected={selected}
          onSelect={iso3 => setSelected(iso3 === selected ? null : iso3)}
          severityColor={severityColor}
        />

        {/* Zoom controls */}
        <div style={{ position: 'absolute', top: 14, right: 14, zIndex: 10, display: 'flex', flexDirection: 'column', gap: 6 }}>
          {['+', '−', '⊙'].map(icon => (
            <button
              key={icon}
              onClick={() => {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const map = (window as any).__aletheiaMap
                if (!map) return
                if (icon === '+') map.zoomIn()
                else if (icon === '−') map.zoomOut()
                else map.fitBounds([[-58, -120], [74, -30]])
              }}
              style={{
                width: 30, height: 30,
                background: 'rgba(11,21,38,.8)', border: '1px solid var(--line-2)',
                color: 'var(--text-3)', fontSize: 14, cursor: 'pointer',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                backdropFilter: 'blur(4px)',
                transition: 'border-color .15s, color .15s',
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--accent)'; e.currentTarget.style.color = 'var(--text)' }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--line-2)'; e.currentTarget.style.color = 'var(--text-3)' }}
            >
              {icon}
            </button>
          ))}
        </div>

        {/* Map hint */}
        <div style={{ position: 'absolute', top: 14, right: 60, zIndex: 10, background: 'rgba(11,21,38,.8)', border: '1px solid var(--line-2)', padding: '7px 12px', backdropFilter: 'blur(4px)' }}>
          <span style={{ fontFamily: 'var(--mono)', fontSize: 8, letterSpacing: '0.1em', color: 'var(--text-3)', textTransform: 'uppercase' }}>
            Haz clic en un país
          </span>
        </div>

        {/* Legend */}
        <div style={{ position: 'absolute', bottom: 14, left: 14, zIndex: 10, background: 'rgba(11,21,38,.85)', border: '1px solid var(--line-2)', padding: '10px 14px', backdropFilter: 'blur(4px)' }}>
          <div style={{ fontFamily: 'var(--mono)', fontSize: 7.5, color: 'var(--text-3)', letterSpacing: '0.14em', textTransform: 'uppercase', marginBottom: 7 }}>
            Índice IEA 2023 · Corrupción estimada
          </div>
          <div style={{ width: 132, height: 4, background: 'linear-gradient(to right, #22d3a0, #facc15, #fb923c, #f43f5e)', marginBottom: 4 }} />
          <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: 'var(--mono)', fontSize: 7.5, color: 'var(--text-4)' }}>
            <span>Bajo</span><span>Moderado</span><span>Alto</span><span>Crítico</span>
          </div>
        </div>
      </div>

      {/* ── Right: Country panel ─────────────────────────── */}
      <AnimatePresence>
        {selected && (
          <motion.div
            key="panel"
            initial={{ x: 372, opacity: 0 }}
            animate={{ x: 0,   opacity: 1 }}
            exit={{ x: 372,    opacity: 0 }}
            transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
            style={{ borderLeft: '1px solid var(--line-2)', overflow: 'hidden', display: 'flex', flexDirection: 'column', height: '100%' }}
          >
            <CountryPanel iso3={selected} onClose={() => setSelected(null)} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}
